void midi() {
  int numTones = sizeof(tones) / sizeof(tones[0]);
  
  for (int i = 0; i < numTones; i++) {
    unsigned int toneValue = pgm_read_word(&tones[i]);
    
    if (toneValue == 0) {
      // Delay
      delay(delayTime);
    } else if (toneValue >= 1000) {
      // Long duration note (L prefix)
      tone(tonePin, toneValue - 1000, longDur);
    } else {
      // Regular note
      tone(tonePin, toneValue, dur);
    }
    delay(delayTime);
  }
}